// Monta UMA mensagem agregando todas tarefas due, com tom natural variado.
const THIAGO_NUMERO = '5511910441709';
const tarefas = items.filter(i => i.json && i.json.titulo);
if (!tarefas.length) return [];

// Hora atual Brasilia
const agora = new Date(Date.now() - (3 * 60 * 60 * 1000));
const hora = agora.getHours();
let saudacao = '';
if (hora < 12) saudacao = 'Bom dia';
else if (hora < 18) saudacao = 'Boa tarde';
else saudacao = 'Boa noite';

// agrupar por urgencia
const atrasadas = tarefas.filter(t => t.json.urgencia === 'atrasada');
const hoje = tarefas.filter(t => t.json.urgencia === 'hoje');
const outras = tarefas.filter(t => t.json.urgencia === 'normal');

let partes = [];
if (atrasadas.length) {
  partes.push('Atrasadas (passou do prazo):\n' + atrasadas.map(t => `- #${t.json.id} ${t.json.titulo}`).join('\n'));
}
if (hoje.length) {
  partes.push((atrasadas.length ? '\n' : '') + 'Pra hoje:\n' + hoje.map(t => `- #${t.json.id} ${t.json.titulo}`).join('\n'));
}
if (outras.length) {
  const tit = (atrasadas.length || hoje.length) ? '\nOutras pendentes:' : 'Pendentes:';
  partes.push(tit + '\n' + outras.map(t => `- #${t.json.id} ${t.json.titulo}`).join('\n'));
}

const total = tarefas.length;
let abertura;
if (atrasadas.length) abertura = `${saudacao}, oh, tem ${atrasadas.length} tarefa${atrasadas.length>1?'s':''} atrasada${atrasadas.length>1?'s':''}.`;
else if (hoje.length) abertura = `${saudacao}. Hoje tem ${hoje.length} pra fazer.`;
else abertura = `${saudacao}, te lembrando das pendentes.`;

const fechamento = total === 1
  ? '\n\nJa fez? Manda "feito" se ja resolveu ou "adia" pra empurrar.'
  : '\n\nMe avisa o que ja foi feito ("feito #ID") ou "adia #ID" pra empurrar.';

const texto = abertura + '\n\n' + partes.join('\n') + fechamento;

// SQL pra atualizar cobranca em todas
const ids = tarefas.map(t => t.json.id).join(',');
const sqlUpdate = `UPDATE giulia_tarefas SET ultima_cobranca_em = NOW(), cobranca_count = cobranca_count + 1, proxima_cobranca_em = NOW() + INTERVAL '4 hours', ultima_msg_giulia = LEFT('${texto.replace(/'/g, "''").substring(0, 1500)}', 1500) WHERE id IN (${ids});`;

return [{ json: { send_to: THIAGO_NUMERO, send_text: texto, sql_update: sqlUpdate } }];
